const knowledge=/名著|红楼梦|西游记|鲁迅|莎士比亚|陀思妥耶夫斯基|卡夫卡|思想|人文|艺术|文学|哲学|文化|伦理|社会|经济|政治|心理|认知|意识|科学|研究|科技|人工智能|神经|算法|宇宙|量子|生物|生态|哲学|科普|philosoph|ethic|conscious|cognit|psycholog|societ|culture|literature|art\b|scien|research|intelligence|econom|politic|technolog/iu;
export function text(value=''){return String(value).replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,'').replace(/<[^>]*>/g,'').replace(/&#(?:x([\da-f]+)|(\d+));/gi,(_,h,d)=>{const n=parseInt(h||d,h?16:10);return n<=1114111?String.fromCodePoint(n):''}).replace(/&(?:amp|lt|gt|quot|apos|#39|nbsp|rsquo|lsquo|rdquo|ldquo|mdash|ndash);/g,x=>({'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&apos;':"'",'&#39;':"'",'&nbsp;':' ','&rsquo;':'’','&lsquo;':'‘','&rdquo;':'”','&ldquo;':'“','&mdash;':'—','&ndash;':'–'}[x])).replace(/\s+/g,' ').trim()}
export function seconds(value){if(typeof value==='number')return value;return String(value||'').split(':').reduce((n,x)=>n*60+(Number(x)||0),0)}
export function count(value){if(value===undefined||value===null||value==='')return null;const n=parseFloat(String(value).replace(/,/g,''));if(!Number.isFinite(n))return null;return Math.round(n*(String(value).includes('亿')?1e8:String(value).includes('万')?1e4:1))}
export function exclusionReason(item){const label=`${item.title||''} ${item.tags||''} ${item.category||''}`;if(divination.test(label+' '+(item.desc||'')))return '占卜与非科学预测';if(trivia.test(label))return '趣味问答';if(adultMeme.test(label+' '+(item.desc||'')))return '成人恶搞';if(politics.test(label+' '+(item.desc||'')))return '政治';if(pseudoscience.test(label+' '+(item.desc||'')))return '伪科学宣传';if(entertainment.test(label))return '娱乐';if(excluded.test(label))return '历史、基础教育或考试录播';if(item.kind!=='article'&&(collections.test(label)||item.isCollection||item.parts>1))return '合集';if(item.kind!=='article'&&universityMath.test(label))return '大学数学课程';if(item.kind!=='article'&&(!(Number(item.followers)>10000)||item.creatorVerified!==true))return '作者未认证、粉丝不足或无法核实';if(!(item.curated||knowledge.test(label+' '+(item.desc||''))))return '非深度知识候选';return null}
export function isKnowledge(item){return !exclusionReason({...item,kind:'article'},0)&&!((item.kind!=='article')&&(collections.test(item.title||'')||universityMath.test(item.title||'')||item.parts>1||item.isCollection))}
export function eligible(item){return exclusionReason(item)===null}
const aliases={'文学':['literature','literary'],'名著':['classic','novel','literature'],'哲学':['philosoph','ethic'],'人文':['humanit','culture','literature'],'意识':['conscious','mind'],'心理':['psycholog','mind'],'认知':['cognit','mind'],'社会':['societ','social'],'文化':['cultur'],'科技':['technolog','intelligence'],'人工智能':['artificial intelligence',' ai '],'科学':['scien','research'],'量子':['quantum'],'生物':['biolog'],'伦理':['ethic'],'深度':[],'科普':[],'知识':[]};
export function relevant(item,query=''){const terms=query.normalize('NFKC').toLowerCase().trim().split(/\s+/u).filter(t=>!['深度','科普','知识','内容','思考'].includes(t));const haystack=` ${item.title} ${item.desc||''} ${item.author||''} ${item.tags||''} ${(item.pages||[]).map(p=>p.part).join(' ')} `.normalize('NFKC').toLowerCase();return terms.every(t=>[t,...(aliases[t]||[])].some(a=>haystack.includes(a)))}
export function inferTopic(value){if(classicLiterature.test(value))return '经典名著';return /伦理|人工智能|算法|technolog|intelligence|algorithm|ethic/iu.test(value)?'科技与伦理':/心理|认知|意识|psycholog|cognit|conscious|mind/iu.test(value)?'心理与认知':/社会|经济|政治|文化|societ|econom|politic|culture|law/iu.test(value)?'社会与文化':/宇宙|量子|科学|物理|生物|数学|research|scien|quantum|biolog/iu.test(value)?'前沿科学':'哲学与人文'}
export function normalizeVideo(raw,extra={}){const bvid=String(raw.bvid||'');if(!/^BV[0-9A-Za-z]{10}$/.test(bvid))throw Error('Invalid BVID');const cover=String(raw.pic||'').replace(/^http:/,'https:').replace(/^\/\//,'https://');if(!/^https:\/\/i[0-9]\.hdslb\.com\//.test(cover))throw Error('Invalid cover');return {id:bvid,bvid,mid:String(raw.owner?.mid||raw.mid||''),kind:'video',provider:'bilibili',title:text(raw.title),desc:text(raw.desc||raw.description),cover,author:text(raw.owner?.name||raw.author),source:'B站',format:'视频',topic:inferTopic(`${raw.title} ${raw.tag||''}`),tags:text(raw.tag||extra.tags||''),duration:seconds(raw.duration),dimension:raw.dimension||raw.pages?.[0]?.dimension||null,views:count(raw.stat?.view??raw.play??raw.view),parts:Number(raw.videos||raw.pages?.length||1),isCollection:(raw.is_union_video===true||Number(raw.is_union_video)>0),category:text(raw.tname||raw.typename),curated:extra.curated===true,url:`https://www.bilibili.com/video/${bvid}/`,pages:(raw.pages||[]).slice(0,200).map((p,i)=>({page:i+1,part:text(p.part),duration:seconds(p.duration)}))}}
